import { Component, Injector, inject } from '@angular/core';
import { AbstractControl, ReactiveFormsModule } from '@angular/forms';
import { MODULE_NAME } from 'espd-common/config';
import { FormsModule, SelectOption } from 'espd-common/forms';
import { EspdAbstractSizeableInputDirective, EspdFormControl, EspdFormGroup } from 'espd-common/forms/api';
import { MessageService } from 'espd-common/i18n';
import { FontService } from './font.service';

export interface FontFamilyModel {
	[K: string]: AbstractControl<any>;
	fontFamily: EspdFormControl<string | null>;
	fontFaceName: EspdFormControl<string>;
	fallback: EspdFormControl<string>;
}

@Component({
	selector: 'espd-font-family',
	templateUrl: './font-family.component.html',
	styleUrls: ['./font-family.component.scss'],
	imports: [
		ReactiveFormsModule,
		FormsModule
	],
	providers: [
		FontService
	]
})
export class FontFamilyComponent extends EspdAbstractSizeableInputDirective<EspdFormGroup<FontFamilyModel>> {

	public fontFamilyOptionsWithCustom: SelectOption[] = [];
	public fontFamilyOptions: SelectOption[] = [];

	public messageService = inject(MessageService);
	private fontService = inject(FontService);

	constructor() {
		super(inject(Injector));
		this.messageService.waitFor(MODULE_NAME).subscribe(() => {
			this.setupPage();
		});
	}

	public get fontFamilyControlValue(): string | null {
		return this.control.get('fontFamily')?.value ?? null;
	}

	private setupPage(): void {
		this.fontFamilyOptions = this.fontService.getPredefinedFontFaces().map(kv => [kv.key, kv.value]);
		this.fontFamilyOptionsWithCustom = this.fontService.getPredefinedFontFaces().map(kv => [kv.key, kv.value]);
		this.fontFamilyOptionsWithCustom.push([null, this.messageService.get('common.font.predefined.custom')]);
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}